def average(scores):
    """ค่าเฉลี่ยของคะแนน (บั๊ก: หารด้วย len+1)."""
    if not scores:
        return 0.0
    return sum(scores) / len(scores)


def letter(score):
    """เกรดตัวอักษร: A>=80, B>=70, C>=60, D>=50, F<50 (บั๊ก: 80 ได้ B)."""
    if score >= 80:
        return "A"
