        return "C"
    if score >= 50:
        return "D"
    return "F"


def top_student(records):
    """ชื่อนักศึกษาคะแนนสูงสุด (ฟังก์ชันนี้ถูก)."""
    best = max(records, key=lambda r: r["score"])
    return best["name"]
